BEGIN;

SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (182::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-24T00:00:00+00:00'::TIMESTAMPTZ, '01a7403059712695e3e94611e4dc448c6625b4829720f56c3e79b5e6feae735b'::TEXT, ARRAY[493]::BIGINT[]),
    (182::BIGINT, 'Me gustó mucho las clases con él. Son solo jugar varios juegos y deportes, me gustó cuando jugamos Voleibol. 100% recomendado, solo no faltes, haz la propuesta lúdica y ya pasaste!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-16T00:00:00+00:00'::TIMESTAMPTZ, '797b5e34e8fe853ec312a63167a2cb9af8c32219e9b1d2b3fb061504dd5bfe00'::TEXT, ARRAY[493]::BIGINT[]),
    (182::BIGINT, 'Con Rodrigo es el espacio para despejarse y tener un rato de diversión y relajación de todo lo de la u. Se disfruta mucho jugar y volver a ser niño por un rato y aún más con sus lindas reflexiones de vida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Inspirador']::TEXT[], '2024-12-12T00:00:00+00:00'::TIMESTAMPTZ, '809e8ded5987ada05ad4c091869b002dbad4dc0267cd303633b45fc9c70327fc'::TEXT, ARRAY[493]::BIGINT[]),
    (182::BIGINT, 'el profe rodrigo es mi papá, lo amo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'e2cdab5d40411fa8c0ce8d208b9b6d098f7758c4829239183cdc0c7efa2b1dcd'::TEXT, ARRAY[493]::BIGINT[]),
    (182::BIGINT, 'Es el mejor profe de la escuela. Una persona sumamente alegre, agradable y humana. La dinámica es super linda y se pasa super bien con los otros compañeros. Durante los estiramientos hay reflexiones muy buenas y el profe es muy comprensivo. Si no falta y participa se pasa solo el curso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, '03417811b783fe6ae23d47a364b41332d0922a6475bc486f41e80826a070defb'::TEXT, ARRAY[493]::BIGINT[]),
    (182::BIGINT, 'El profe hace que el curso sirva para botar el estrés del semestre. Es un curso super bonito donde se llega a jugar y pasar un buen rato con lxs demás. El profe a veces hace reflexiones mientras se hacen los estiramientos. Al final del semestre hicimos un desayuno compartido super bonito'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2023-06-18T00:00:00+00:00'::TIMESTAMPTZ, '5c98e83897203bee164a9da1e9d71ec6f9e91c97a1f90eb31b3e5a885d6e5fca'::TEXT, ARRAY[493]::BIGINT[]),
    (182::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2023-04-12T00:00:00+00:00'::TIMESTAMPTZ, '5a4ec2606d06ca649203bc03db11b8180d0c4f7b31c743afedb8be76dfa19b21'::TEXT, ARRAY[493]::BIGINT[]),
    (182::BIGINT, 'El profe es un amor de persona, hace que la clase sea completamente diferente y ayude a bajar por un rato el estrés que da el resto de cursos, todas las semanas se aprende sobre una disciplina diferente, además el sabe muchísimo, super recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'f7585259ccb495621f86fa8e1441289f8cd0300d79e5eb352ce4c888f2c974b3'::TEXT, ARRAY[574]::BIGINT[]),
    (182::BIGINT, 'Excelente profe. Brinda mucho apoyo. Explica muy bien, al iniciar la clase da una reflexión y hace muy bonita la clase ya que es una excelente persona.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, '37391f16a870462317503466f40aefbcb4ae55925b3abbabc05229477de5e632'::TEXT, ARRAY[493]::BIGINT[]),
    (182::BIGINT, 'El profe es muy pura vida, la clase es un poco aburrida, pero las actividades sí son interesantes y fáciles. Tiene que asistir a la reunión y participar de vez en cuando, aparte de hacer el trabajo semanal.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-23T00:00:00+00:00'::TIMESTAMPTZ, '9f11cf8f91177099db559611a57fe6f932917e0d1fda6b560be5aacfbea45219'::TEXT, ARRAY[574]::BIGINT[]),
    (182::BIGINT, 'Con este profe el curso virtual se pasa muy fácil, solo hay que enviar un portafolio semanal con evidencia de los ejercicios realizados para esa semana. Asistencia obligatoria a clases (pasa lista), el único problema es que la esa clase es eterna, el profe habla de más. Por lo demás, lo recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas']::TEXT[], '2021-10-15T00:00:00+00:00'::TIMESTAMPTZ, '3085129d2c2fa05958d1e71d816903e33152264399cf9a7b679b42b660bf8c76'::TEXT, ARRAY[574]::BIGINT[]),
    (182::BIGINT, 'Super carga, excelente profesor, se adapto muy bien a la virtualidad. Explica las actividades y el juego en la clase sincronica y se entrega unas evidencias super faciles cada semana, es flexible con las entregas y entiende si uno no puede entregar el portafolio o no pude hacer la actividad,'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, '283fe6473da2d4bc2d626e3e2ea2b3faa963b3cc4aac8bb6297e4d435272ecd1'::TEXT, ARRAY[493]::BIGINT[]),
    (182::BIGINT, 'Muy buen profe, a veces se emociona y se le va el tiempo hablando. Mi profesor favorito hasta ahora'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2021-02-11T00:00:00+00:00'::TIMESTAMPTZ, 'f21900af656a38612e6fa5eec6240178d14d1c2b7e2f72235a3691dd25280dbd'::TEXT, ARRAY[493]::BIGINT[]),
    (182::BIGINT, 'Él curso virtual con él es súper fácil, y se ve muy buena gente, no nos puso a comprar material, y las evidencias de los ejercicios son formularios y fotos. El problema es que habla mucho, y la clase a veces toma más de las 2 horas a la semana pues la asistencia es obligatoria más hacer la rutina.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Clases largas']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '2ada519ca06317f3272ea6344a1b8447c64c199987c27d40030d5ac90f0c5daa'::TEXT, ARRAY[493]::BIGINT[]),
    (182::BIGINT, 'La clase en sí fue extremadamente fácil ya que solo es conectarse a la clase y hacer un documento semanal de evidencias de diferentes deportes que es fácil de hacer. El profe cae muy muy bien e inspira a los estudiantes, y básicamente es genial.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Inspirador', 'Brinda apoyo']::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, '44d4b886c162edd63658aacf2743dbab64663bd381ceb6308a8f97ef34f2370e'::TEXT, ARRAY[493]::BIGINT[]),
    (182::BIGINT, 'El profe es un amor, se nota que le apasiona lo que hace, siempre da motivación al inicio de la clase y es excelente en general, se pone en el lugar de los estudiantes y siempre esta dispuesto a ayudar. de los mejores del tec'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Brinda apoyo']::TEXT[], '2021-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'cf807443700387dae4d7672ad92694dbcf6c6b3f6c8ba62117782da2149dfa06'::TEXT, ARRAY[574]::BIGINT[]),
    (182::BIGINT, 'Llevarla virtual es un chiste, solo es ir a clases y rellenar una hoja de evidencias (que es solo hacer una fotillo ahí jaja no hay que hacer nada) . Las clases son solo el hablando. Literal puede conectarse y dejarlo ahí mientras hace otras cosas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2020-12-20T00:00:00+00:00'::TIMESTAMPTZ, '794ff5dabaec55b38ebb5796bd13a7d48d1074dbcc8e6d9451efadf053d08d25'::TEXT, ARRAY[493]::BIGINT[]),
    (182::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, '99c52be076b1052c22a0a1aafb8bfe53a4e3c7a964fe3ae5260cba14a3eab66d'::TEXT, ARRAY[493]::BIGINT[]),
    (182::BIGINT, 'Es un amor como profe y como persona. Le apasiona el Atletismo entonces le importa demasiado la asistencia y que todos aprendan. Las clases son entretenidas. Muy recomendado. Hay que hacer un par de talleres extracurriculares.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2020-02-03T00:00:00+00:00'::TIMESTAMPTZ, '9dbbdf81347c4959dc4cedc8f60e26786b5fc9157a86cd25e9f8a284b6a5b382'::TEXT, ARRAY[574]::BIGINT[]),
    (182::BIGINT, 'Excelente profesor. Muy buena nota. Se toma la clase de atletismo MUY en serio, el curso en un poco cansado pero se aprende. Con solo ir a clases se aprueba (como cualquier deportiva)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2019-07-15T00:00:00+00:00'::TIMESTAMPTZ, '4a73728d30693d564e48992aaecaa9f31cafd2939ea2354a7dab1cc92076bb96'::TEXT, ARRAY[574]::BIGINT[]),
    (182::BIGINT, 'Muy buen profe, muy pura vida. Nada más no faltar a clases y participar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'c8dbb4e5cbff24d18e1e20d193705177ff8c7a622ed3550852f90acf9b5b3b09'::TEXT, ARRAY[493]::BIGINT[]),
    (182::BIGINT, 'Muy buen profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '4f4a3d15cafc9fbd70e14922aeb9896e8647b0c42208061e2be8e5e6e50736d1'::TEXT, ARRAY[493]::BIGINT[]),
    (182::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'ee3983259743bce196ff61dde943c8fc0c672789bec4155a7d5428d7ab7a1399'::TEXT, ARRAY[574]::BIGINT[]),
    (182::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2019-05-28T00:00:00+00:00'::TIMESTAMPTZ, '9804692a3c6cab760822a20664ef84a4b2d354b0fcf4ea21a166df7bc7645c48'::TEXT, ARRAY[493]::BIGINT[]),
    (182::BIGINT, 'Hace muy divertido el curso. Se ven deportes diferentes, como el korfball y el fútbol americano. Es bastante comprensivo y respetuoso. Llevaría de nuevo el curso si pudiera :D'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2018-12-11T00:00:00+00:00'::TIMESTAMPTZ, '86f65adf5fa7e760062743ec76e6818e1876e791ceccd9707f2863ed2845cedc'::TEXT, ARRAY[493]::BIGINT[]),
    (182::BIGINT, 'Una gran persona que conoce de su trabajo. Las clases son divertidas y sirven para salir de la rutina del estudio. Le gusta mucho el balón mano y realiza un torneo de este deporte que es super interesante. Muy amable , respetuoso, comprensivo y pura vida. Recomendado :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Inspirador']::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, '75756de7104fd89bddf52cc4cd5339dc9467a313798ecac94176466eb5a53659'::TEXT, ARRAY[493]::BIGINT[]),
    (182::BIGINT, 'La mejor deportiva que existe, séper recomendado!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-20T00:00:00+00:00'::TIMESTAMPTZ, '32417920672e6e6a40432268fe971900e5c1f6867aeb9f193b1919c23fc4b4a1'::TEXT, ARRAY[493]::BIGINT[]),
    (182::BIGINT, 'Llevelo con él, es super tuanis.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'cac75870bd7b8fcb0ed41ac77ec542b8e8fe4db323b9c22eb3610fb2ffdde3fc'::TEXT, ARRAY[493]::BIGINT[]),
    (182::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-02-14T00:00:00+00:00'::TIMESTAMPTZ, '084e5dc6f1a54a5a2087bf1dc6071d910dc2b4cda66d727887ddc626f1b3579f'::TEXT, ARRAY[574]::BIGINT[]),
    (182::BIGINT, 'Excelente profesor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '37b9faae5ebbda6015f3811eea6fe444e0302bcb8ec21ade8079499cba393d58'::TEXT, ARRAY[493]::BIGINT[]),
    (182::BIGINT, 'Podría ser aún más dinámica la clase, pero todo bien'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-09-21T00:00:00+00:00'::TIMESTAMPTZ, '7bcb1e42969fde1741142d3e59307e61cdd33dfd3823c5a16b108075bc694aaf'::TEXT, ARRAY[493]::BIGINT[]),
    (182::BIGINT, 'Muy pura vida el profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'fb2460ae134a534b63421b030a670a325f5cc4f1f5de4238cee4d97e7e16e317'::TEXT, ARRAY[493]::BIGINT[]),
    (182::BIGINT, 'Muy buen profesor y profesional. Sabe lo que hace y la pasión por lo que hace se le nota y se transmite a la clase. Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Inspirador', 'Brinda apoyo']::TEXT[], '2016-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'ae1db3a60d1d6f7bbe8c8c52a59cc803b80216c3928eb6536738a686eca81a84'::TEXT, ARRAY[574]::BIGINT[]),
    (182::BIGINT, 'Excelente clase. Hace la clase entretenida y cada clase es distinta a la anterior, es un curso muy completo acerca del atletismo, uno aprende mucho y es entretenido. Es muy comprensivo con situaciones personales'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '04bbea6c39a2185262e663616f51d9a4547357013ea0602c3065bdffade04039'::TEXT, ARRAY[574]::BIGINT[]),
    (182::BIGINT, 'Es bueno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2016-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'd05e306e8dc7916fbd30138563459c17c1d4ee5e5de7682129682f726ada59a5'::TEXT, ARRAY[493]::BIGINT[]),
    (182::BIGINT, 'Hace lo que se espera de un profe de deportiva y mantiene la clase interesante. Muy comprensivo con los estudiantes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'fcd40a2cf58d88a67064f0a12bb99058c302715b5fb782d303332164e7b67047'::TEXT, ARRAY[574]::BIGINT[]),
    (182::BIGINT, 'Excelente profesor!! Muy respetuoso y se enfoca en que la gente aprenda y se divierta. Con las situaciones personales es muy comprensivo. Ojo que también toma mucho en cuenta la puntualidad y asistencia'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'e85f6c7dbbe0f8d681eab8418f9d062f28a448beaf119449ddb0d9d1e42dc5b7'::TEXT, ARRAY[574]::BIGINT[]),
    (182::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-04T00:00:00+00:00'::TIMESTAMPTZ, '324b8431550b1451a9797f339b2733fc6d19e96d458fc26b340a9ba9353fe680'::TEXT, ARRAY[574]::BIGINT[]),
    (182::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-03T00:00:00+00:00'::TIMESTAMPTZ, '3bd7694af11466c7021bf23aa82c167c7334844d56dc43f2fc19fc4bc60e576f'::TEXT, ARRAY[574]::BIGINT[]),
    (182::BIGINT, 'Un curso divertido, es muy comprensivo, si uno tiene alguna situación pero si toma mucho en cuenta la puntualidad y asistencia así como la participación en clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-14T00:00:00+00:00'::TIMESTAMPTZ, '8a3863cef4b3d98c9849db47ff148e924c912ae7cde607f1e50a69f7f10639cf'::TEXT, ARRAY[493]::BIGINT[]),
    (182::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'edd158e3a1993d7bc9975baf81f61bcf122e52ac9c34de45ae949263cb58eab3'::TEXT, ARRAY[493]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
